alter table public.organizations enable row level security; alter table public.profiles enable row level security; alter table public.organization_members enable row level security; alter table public.properties enable row level security; alter table public.property_users enable row level security; alter table public.rooms enable row level security; alter table public.guests enable row level security; alter table public.reservations enable row level security; alter table public.enquiries enable row level security; alter table public.conversations enable row level security; alter table public.conversation_messages enable row level security; alter table public.knowledge_categories enable row level security; alter table public.knowledge_items enable row level security; alter table public.tasks enable row level security; alter table public.reviews enable row level security; alter table public.digital_audits enable row level security; alter table public.audit_items enable row level security; alter table public.automations enable row level security; alter table public.automation_runs enable row level security; alter table public.integrations enable row level security; alter table public.guest_journey_events enable row level security; alter table public.tax_profiles enable row level security; alter table public.tax_transactions enable row level security; alter table public.mgis_records enable row level security; alter table public.notifications enable row level security; alter table public.audit_logs enable row level security;
create policy profiles_self on public.profiles for all using(id=auth.uid()) with check(id=auth.uid());
create policy org_members_self_or_admin on public.organization_members for select using(user_id=auth.uid() or public.is_org_admin(organization_id));
create policy org_admin_write on public.organization_members for all using(public.is_org_admin(organization_id)) with check(public.is_org_admin(organization_id));
create policy organizations_member_read on public.organizations for select using(public.is_org_member(id));
create policy organizations_admin_write on public.organizations for all using(public.is_org_admin(id)) with check(public.is_org_admin(id));
create policy properties_member_read on public.properties for select using(public.is_org_member(organization_id));
create policy properties_admin_write on public.properties for all using(public.is_org_admin(organization_id)) with check(public.is_org_admin(organization_id));
create policy property_users_member_read on public.property_users for select using(public.is_property_member(property_id));
create policy property_users_admin_write on public.property_users for all using(public.is_property_admin(property_id)) with check(public.is_property_admin(property_id));
create policy rooms_access on public.rooms for all using(public.is_property_member(property_id)) with check(public.is_property_member(property_id));
create policy guests_access on public.guests for all using(public.is_org_member(organization_id)) with check(public.is_org_member(organization_id));
create policy reservations_access on public.reservations for all using(public.is_property_member(property_id)) with check(public.is_property_member(property_id));
create policy enquiries_access on public.enquiries for all using(public.is_property_member(property_id)) with check(public.is_property_member(property_id));
create policy conversations_access on public.conversations for all using(public.is_property_member(property_id)) with check(public.is_property_member(property_id));
create policy messages_access on public.conversation_messages for all using(exists(select 1 from public.conversations c where c.id=conversation_id and public.is_property_member(c.property_id))) with check(exists(select 1 from public.conversations c where c.id=conversation_id and public.is_property_member(c.property_id)));
create policy knowledge_categories_access on public.knowledge_categories for all using(public.is_property_member(property_id)) with check(public.is_property_member(property_id));
create policy knowledge_access on public.knowledge_items for all using(public.is_property_member(property_id)) with check(public.is_property_member(property_id));
create policy tasks_access on public.tasks for all using(public.is_property_member(property_id)) with check(public.is_property_member(property_id));
create policy reviews_access on public.reviews for all using(public.is_property_member(property_id)) with check(public.is_property_member(property_id));
create policy audits_access on public.digital_audits for all using(public.is_org_member(organization_id)) with check(public.is_org_member(organization_id));
create policy audit_items_access on public.audit_items for all using(exists(select 1 from public.digital_audits a where a.id=audit_id and public.is_org_member(a.organization_id))) with check(exists(select 1 from public.digital_audits a where a.id=audit_id and public.is_org_member(a.organization_id)));
create policy automations_access on public.automations for all using(public.is_property_member(property_id)) with check(public.is_property_member(property_id));
create policy automation_runs_access on public.automation_runs for all using(exists(select 1 from public.automations a where a.id=automation_id and public.is_property_member(a.property_id))) with check(exists(select 1 from public.automations a where a.id=automation_id and public.is_property_member(a.property_id)));
create policy integrations_access on public.integrations for all using(public.is_org_member(organization_id)) with check(public.is_org_member(organization_id));
create policy journey_access on public.guest_journey_events for all using(public.is_property_member(property_id)) with check(public.is_property_member(property_id));
create policy tax_profiles_access on public.tax_profiles for all using(public.is_property_member(property_id)) with check(public.is_property_member(property_id));
create policy tax_transactions_access on public.tax_transactions for all using(public.is_property_member(property_id)) with check(public.is_property_member(property_id));
create policy mgis_access on public.mgis_records for all using(public.is_property_member(property_id)) with check(public.is_property_member(property_id));
create policy notifications_self on public.notifications for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy audit_logs_member_read on public.audit_logs for select using(organization_id is null or public.is_org_member(organization_id));
create policy audit_logs_member_insert on public.audit_logs for insert with check(actor_user_id=auth.uid() and (organization_id is null or public.is_org_member(organization_id)));
